func newEnrollmentSettingsApplyCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		fromFile     string
		flagYes      bool
		flagDryRun   bool
		flagScaffold bool
	)

	cmd := &cobra.Command{
		Use:         "apply",
		Short:       "Create or replace a enrollment-setting by name",
		Annotations: map[string]string{"jamf:api": "pro"},
		Long: `Create or replace a enrollment-setting. Reads JSON or YAML from --from-file or stdin.

The name field in the input is used to check if the resource
already exists. If it does, the resource is replaced (with confirmation).
If not, a new resource is created.`,
		Example: `  # Apply a enrollment-setting from a JSON file
  jamf-cli pro enrollment-settings apply --from-file enrollment-setting.json

  # Apply a enrollment-setting from a YAML file
  jamf-cli pro enrollment-settings apply --from-file enrollment-setting.yaml

  # Apply from stdin
  cat enrollment-setting.json | jamf-cli pro enrollment-settings apply

  # Apply without replacement confirmation
  jamf-cli pro enrollment-settings apply --from-file enrollment-setting.json --yes

  # Preview what would happen
  jamf-cli pro enrollment-settings apply --from-file enrollment-setting.json --dry-run`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			reqCtx := cmd.Context()
			if flagScaffold {
				return printScaffoldOutput(`{
  "accountDrivenUserEnrollmentEnabled": false,
  "enterpriseEnrollmentEnabled": false,
  "groupId": "1",
  "ldapServerId": "1",
  "name": "Grade School Pupils",
  "personalEnrollmentEnabled": false,
  "requireEula": false,
  "siteId": "-1"
}`, ctx.Output.Format())
			}

			// Read input (JSON or YAML). When file flags are present, empty input
			// is OK — the file-field injector constructs a minimal body.
			data, err := readApplyInput(fromFile)
			if err != nil {
				return err
			}
			if len(data) > 0 {
				data, err = normalizeInputToJSON(data)
				if err != nil {
					return err
				}
			}

			// Extract name from JSON input
			name, err := extractJSONField(data, "name")
			if err != nil {
				return fmt.Errorf("input must include a %q field: %w", "name", err)
			}

			// Check if resource exists by name (read-only, runs even in dry-run)
			noInput, _ := cmd.Flags().GetBool("no-input")
			id, err := resolveNameToIDForApply(reqCtx, ctx.Client, "/v3/enrollment/access-groups", "name", "id", name, noInput)
			if err != nil {
				return err
			}

			if id == "" {
				// Not found — create
				if flagDryRun {
					fmt.Fprintf(os.Stderr, "[dry-run] Would create enrollment-setting %q\n", name)
					return nil
				}
				resp, err := ctx.Client.Do(reqCtx, "POST", "/v3/enrollment/access-groups", bytes.NewReader(data))
				if err != nil {
					return err
				}
				defer resp.Body.Close()
				fmt.Fprintf(os.Stderr, "Created enrollment-setting %q\n", name)
				return ctx.Output.PrintResponse(resp)
			}

			// Found — replace
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would replace enrollment-setting %q (id: %s)\n", name, id)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("enrollment-setting %q already exists (id: %s); use --yes to replace when --no-input is set", name, id)
				}
				fmt.Fprintf(os.Stderr, "enrollment-setting %q already exists (id: %s) and will be replaced. Type 'yes' to confirm: ", name, id)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			updatePath := strings.Replace("/v3/enrollment/access-groups/{id}", "{id}", url.PathEscape(id), 1)
			resp, err := ctx.Client.Do(reqCtx, "PUT", updatePath, bytes.NewReader(data))
			if err != nil {
				return err
			}
			defer resp.Body.Close()
			fmt.Fprintf(os.Stderr, "Replaced enrollment-setting %q (id: %s)\n", name, id)
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to JSON or YAML input file (or pipe to stdin)")
	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt when replacing")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print a JSON template for the request body and exit")

	return cmd
}
